INSERT IGNORE INTO `pet_breed` (`id`, `category_id`, `name`, `english_name`, `origin`, `personality`, `lifespan`, `weight`, `coat`, `colors`, `description`, `care_tips`, `is_featured`, `sort_order`) VALUES
(1, 1, '英国短毛猫', 'British Shorthair', '英国', '温顺安静、对人友善、独立性强', '12-18年', '4-8kg', '短毛，浓密厚实', '蓝色(经典)、银渐层、金渐层、白色、黑色', '英短是英国最古老的猫品种之一，以圆脸大眼和厚实的被毛闻名。性格温和稳定，非常适合家庭饲养，是优秀的陪伴猫。', '毛短易打理，每周梳毛1-2次即可。易胖体质需控制食量，建议定时定量喂食。喜欢安静环境，不宜频繁变动家庭布置。', 1, 1),
(2, 1, '布偶猫', 'Ragdoll', '美国', '温柔安静、对人依赖、忍耐力强', '12-17年', '4.5-9kg', '中长毛，丝质柔滑', '重点色、手套色、双色(蓝眼)', '布偶猫因在被抱起时会全身放松像布偶一样而得名。性格极其温和，忍耐力强，适合有孩子的家庭。', '中长毛需每日梳理防止打结。肠胃较敏感需注意饮食。性格粘人，不适合长期独处。', 1, 2),
(3, 1, '暹罗猫', 'Siamese', '泰国', '聪明活泼、好奇心强、爱叫爱说话', '12-15年', '3-5kg', '短毛，紧贴皮肤', '海豹重点色、蓝点、巧克力点、淡紫点', '暹罗猫是最古老的东方短毛猫品种之一。以其独特的重点色和湛蓝的眼睛著称。性格外向，非常喜欢与人互动交流。', '短毛易打理。非常怕冷，注意保暖。精力旺盛需要充足的运动和玩具。叫声较大，不适合安静环境。', 1, 3),
(4, 1, '波斯猫', 'Persian', '伊朗(波斯)', '文静温柔、优雅高贵、喜安静', '12-16年', '3.5-7kg', '长毛，浓密蓬松', '白色、蓝色、黑色、红色、奶油色、玳瑁色', '波斯猫以其扁平的面部、圆润的体型和华丽的被毛闻名全球。性格极其安静温和，是典型的陪伴型猫咪。', '长毛需每日梳理。面部扁平易有泪痕需每日清洁。易患多囊肾病，需定期体检。喜安静不喜吵闹。', 1, 4),
(5, 1, '美国短毛猫', 'American Shorthair', '美国', '温和友善、适应力强、身体强健', '15-20年', '4-7kg', '短毛，硬质有光泽', '银色虎斑(经典)、棕色虎斑、金色虎斑、白色', '美短是美国的本土猫种，以健康的体魄和温和的性格著称。非常适合家庭饲养，与孩子和其他宠物相处融洽。', '短毛打理简单。体型健壮不易生病，但需保持适量运动。性格独立但也喜欢主人陪伴。', 0, 5),
(6, 1, '苏格兰折耳猫', 'Scottish Fold', '苏格兰', '温和安静、聪明好奇、适应力好', '12-15年', '3-6kg', '短毛/长毛，柔软浓密', '白色、蓝色、黑色、虎斑、三花、乳色', '以独特的折耳基因为特征，圆圆的脑袋和猫头鹰般的表情十分可爱。性格温和，喜欢安静的家庭环境。', '折耳基因可能伴随骨骼疾病，需定期检查。不宜过度运动。纯种折耳需与立耳交配以避免遗传病。', 0, 6),
(7, 1, '缅因猫', 'Maine Coon', '美国(缅因州)', '温柔亲切、聪明独立、被称为"温柔的巨人"', '12-15年', '5-11kg', '长毛，厚密防水', '棕色虎斑(经典)、黑色、红色、奶油色、银色', '缅因猫是最大的家猫品种之一，公猫可达11公斤。性格却非常温和友善，被称为"温柔的巨人"。', '长毛需每周梳理2-3次。体型大需要更大的活动空间。食量较大，注意营养均衡。', 0, 7),
(8, 1, '中华田园猫', 'Chinese Domestic Cat', '中国', '聪明独立、适应力强、身体素质好', '12-18年', '3-6kg', '短毛，紧致有光泽', '狸花、橘色、黑白、三花、纯白、纯黑', '中华田园猫是中国本土猫种的统称，以狸花猫最为常见。身体素质极佳，聪明独立，捕鼠能力强，是非常优秀的伴侣猫。', '几乎无需专门打理。身体素质好不易生病。性格独立但仍需陪伴。建议定期驱虫和接种疫苗。', 0, 8),
(9, 1, '斯芬克斯猫', 'Sphynx', '加拿大', '活泼友善、好奇心强、非常粘人', '10-15年', '3.5-7kg', '无毛，皮肤柔软有温度', '皮肤色(粉色、灰色、白色、黑色、斑纹)', '斯芬克斯猫以无毛著称，皮肤摸起来温暖光滑。性格极其友善粘人，喜欢被抱着和钻进被窝。', '无毛需定期洗澡去除多余油脂。怕冷需穿衣保暖。皮肤易晒伤不可暴晒。食欲好容易吃多需控制。', 0, 9),
(10, 1, '挪威森林猫', 'Norwegian Forest Cat', '挪威', '温和勇敢、喜欢攀爬、独立性强', '12-16年', '4-9kg', '长毛，双层厚密防水', '棕色虎斑、黑色、白色、红色、蓝色、奶油色', '挪威森林猫是北欧神话中常见的猫种，体型大、被毛厚密，适应寒冷气候。性格温和勇敢，喜欢户外活动。', '长毛需经常梳理特别是换毛季。喜欢攀爬需准备猫爬架。运动量大需要足够活动空间。', 0, 10),
(11, 1, '异国短毛猫', 'Exotic Shorthair', '美国', '安静温顺、慵懒可爱、对人友善', '12-15年', '3.5-7kg', '短毛，厚密绒状', '白色、蓝色、黑色、红色、虎斑、三花、银渐层', '异短是波斯猫的短毛版本，保留了波斯猫的圆脸扁平特征但毛较短。性格安静温顺，喜欢慵懒的生活节奏。', '短毛打理比波斯简便但仍需每周梳理。面部扁平需每天清洁泪痕。喜静不喜动，注意控制体重。', 0, 11),
(12, 1, '孟加拉豹猫', 'Bengal', '美国', '活泼好动、聪明好奇、精力充沛', '12-16年', '4-8kg', '短毛，丝质光泽', '豹纹斑点、大理石纹、金色/银色底色', '孟加拉豹猫是亚洲豹猫和家猫的杂交品种，保留了野性的外观花纹但性格温顺。精力极其旺盛，需要大量活动。', '运动量极大需要大空间和丰富玩具。聪明易学但也会捣蛋。喜欢水是它的独特特点。建议有经验的主人饲养。', 0, 12),
(13, 1, '伯曼猫', 'Birman', '缅甸', '温顺安静、优雅温柔、对人忠诚', '12-16年', '3.5-7kg', '中长毛，丝质光滑', '重点色(海豹、蓝、巧克力、淡紫)白手套', '伯曼猫又称缅甸圣猫，以其白色的"手套"和深蓝色的眼睛著称。性格温和优雅，对主人忠诚温顺。', '中长毛需每周梳理2-3次。性格温顺适合室内饲养。需要主人陪伴不喜欢长时间独处。', 0, 13),
(14, 1, '俄罗斯蓝猫', 'Russian Blue', '俄罗斯', '文静羞涩、聪明优雅、对主人忠诚', '13-17年', '3.5-6kg', '短毛，双层银色光泽', '银蓝色(特征)、绿色眼睛', '俄罗斯蓝猫以其独特的银蓝色被毛和翠绿色眼睛著称。性格文静内敛，对陌生人害羞但对主人非常忠诚。', '短毛易打理。性格敏感需要温和对待。对陌生人害羞，不喜嘈杂环境。', 0, 14),
(15, 1, '阿比西尼亚猫', 'Abyssinian', '埃塞俄比亚', '活泼好动、聪明好奇、精力旺盛', '12-15年', '3-5kg', '短毛，紧致密实', '普通色(红褐色)、蓝色、小鹿色、银灰色', '阿比西尼亚猫被认为是最古老的家猫品种之一，外观酷似古埃及壁画中的猫。性格极其活泼好动，是真正的"猫中哈士奇"。', '精力旺盛需要大量运动和玩具。聪明易训练可以用牵引绳遛猫。粘人但不过分依赖。', 0, 15);
INSERT IGNORE INTO `pet_breed` (`id`, `category_id`, `name`, `english_name`, `origin`, `personality`, `lifespan`, `weight`, `height`, `coat`, `colors`, `description`, `care_tips`, `is_featured`, `sort_order`) VALUES
(16, 2, '阿拉斯加雪橇犬', 'Alaskan Malamute', '美国(阿拉斯加)', '忠诚友好、自信独立、工作欲望强', '10-14年', '34-43kg', '58-64cm', '双层厚毛，外层粗糙', '灰白、黑白、红白、纯白', '阿拉斯加雪橇犬是最古老的极地雪橇犬之一，体格强壮耐力惊人。性格友好忠诚但独立性强，需要坚定而温和的训练。', '厚毛需每周梳理2-3次，换毛季需每日梳理。运动量巨大每日需大量活动。不适合公寓饲养。怕热注意防暑。', 1, 1),
(17, 2, '金毛寻回犬', 'Golden Retriever', '英国(苏格兰)', '友善可靠、聪明温顺、对人友好', '10-14年', '25-34kg', '51-61cm', '中长毛，平直或波浪状', '金色(浅金到深金)', '金毛寻回犬是全球最受欢迎的家庭犬之一，以其温和友善的性格著称。聪明易训练，对大人小孩都极其友好。', '需每周梳理2-3次防打结。运动量中等每日散步1小时。贪吃易胖需控制食量。易患髋关节疾病。', 1, 2),
(18, 2, '拉布拉多寻回犬', 'Labrador Retriever', '加拿大(纽芬兰)', '活泼友善、聪明忠诚、热爱工作', '10-14年', '25-36kg', '55-62cm', '短毛，硬质防水', '黑色、巧克力色、黄色(米色)', '拉布拉多犬是全球最受欢迎的家庭犬种之一，性格友善活泼。金毛和拉布拉多常被混淆，拉拉毛短、精力更旺盛。', '短毛打理简单但掉毛量大。运动量大致需每日1.5小时活动。贪吃易胖需严格控制饮食。', 1, 3),
(19, 2, '哈士奇', 'Siberian Husky', '俄罗斯(西伯利亚)', '友善温和、活泼爱玩、独立固执', '12-15年', '16-27kg', '51-60cm', '双层厚毛，中等长度', '灰白、黑白、红白、银白、纯白', '西伯利亚雪橇犬俗称哈士奇，以其酷似狼的外表和二哈的逗比性格形成巨大反差。友善温和但非常固执。', '厚毛需经常梳理。精力充沛每日需大量运动。拆家能手需充足咬胶和玩具。掉毛量大被誉为"掉毛怪"。', 1, 4),
(20, 2, '彭布罗克威尔士柯基犬', 'Pembroke Welsh Corgi', '英国(威尔士)', '聪明活泼、勇敢友善、警惕性高', '12-15年', '10-14kg', '25-31cm', '中长毛，双层厚密', '红色、貂色、三色(红白黑)、黑色', '柯基犬以其短腿大屁股和狐狸般的外表俘获无数人的心。性格聪明活泼，曾是英国女王最钟爱的犬种。', '需每周梳理2-3次。运动量中等注意控制体重以免腰椎受压。聪明易训练但有自己的想法。', 1, 5),
(21, 2, '法国斗牛犬', 'French Bulldog', '法国', '温和友善、安静乖巧、适应力强', '10-12年', '8-14kg', '28-33cm', '短毛，平滑柔软', '虎斑色、奶油色、白色、黑色', '法斗以其独特的蝙蝠耳和平平面孔成为城市家庭的新宠。性格温和安静，不需要大量运动，非常适合公寓饲养。', '面部褶皱需每日清洁防感染。怕热怕闷注意防暑。运动量小平鼻犬种不宜剧烈运动。注意控制体重。', 1, 6),
(22, 2, '边境牧羊犬', 'Border Collie', '英国(苏格兰边境)', '极其聪明、精力充沛、工作狂', '12-15年', '14-22kg', '46-56cm', '中长毛，双层密实', '黑白(最常见)、红白、蓝陨石、红陨石、三色', '边牧被公认为最聪明的犬种，智商相当于6-8岁儿童。精力极其充沛，是天生的牧羊犬，需要大量活动和脑力游戏。', '聪明但需要大量脑力和体力消耗，否则会搞破坏。每日需至少2小时运动。不适合缺乏运动时间的家庭。', 0, 7),
(23, 2, '德国牧羊犬', 'German Shepherd', '德国', '忠诚勇敢、自信聪明、工作能力强', '9-13年', '22-40kg', '56-66cm', '中长毛，双层密实', '黑褐色(经典)、黑色、灰色、狼灰色', '德牧是全球最出色的工作犬之一，广泛用于警犬、导盲犬等工作。性格忠诚勇敢，对主人极其忠诚。', '需要大量运动和训练，适合有经验的主人。需社交化训练以防过度保护倾向。掉毛量大需经常梳理。', 0, 8),
(24, 2, '萨摩耶犬', 'Samoyed', '俄罗斯(西伯利亚)', '友善温柔、开朗活泼、被称为"微笑天使"', '12-14年', '16-30kg', '48-60cm', '双层厚毛，白色蓬松', '纯白色、奶油色、白色加饼干色', '萨摩耶以其永恒的微笑和雪白的被毛闻名，性格极其友善温柔，是优秀的家庭犬。', '白色厚毛非常难打理，需每日梳理。运动量大，掉毛量极大。性格热情喜欢与人互动。', 0, 9),
(25, 2, '柴犬', 'Shiba Inu', '日本', '独立自信、警觉机敏、忠诚护主', '12-16年', '8-10kg', '35-41cm', '双层厚毛，外层刚硬', '赤色(经典)、黑褐色、胡麻色、奶油色', '柴犬是日本最古老的本土犬种之一，因表情包风靡全球。性格独立自信，有时像猫一样傲娇，对主人忠诚。', '换毛季掉毛量极大。性格倔强训练需要耐心。爱干净会自己打理毛发。有较强领地意识。', 0, 10),
(26, 2, '贵宾犬(泰迪)', 'Poodle (Teddy)', '法国/德国', '聪明活泼、易训练、不掉毛', '12-17年', '4-8kg(迷你)', '24-38cm(迷你)', '卷毛，羊毛状', '白色(最常见)、黑色、棕色、灰色、红色、奶油色、杏色', '贵宾犬以高智商和不掉毛著称，是最受欢迎的家庭犬之一。泰迪是贵宾犬的一种美容造型（并非独立品种）。', '卷毛需每日梳理防打结，定期修剪美容。聪明易训练适合各种犬类运动。运动量适中。', 0, 11),
(27, 2, '英国斗牛犬', 'English Bulldog', '英国', '温和友善、勇敢坚毅、安静沉稳', '8-12年', '18-25kg', '31-40cm', '短毛，平滑', '虎斑色、红色、奶油色、白色、花斑色', '英斗是英国的国犬，以其独特的面部褶皱和壮硕身材著称。虽然外表凶狠，实则性格温和友善。', '面部褶皱需每日清洁。呼吸系统问题多注意防暑。运动量很小适合公寓。易患皮肤病和髋关节问题。', 0, 12),
(28, 2, '博美犬', 'Pomeranian', '德国/波兰', '活泼聪明、警惕性高、对主人忠诚', '12-16年', '1.5-3kg', '18-24cm', '双层长毛，蓬松厚密', '橘色(经典)、白色、黑色、奶油色、蓝色、红色', '博美是体型最小的犬种之一，但性格却很大胆。以其蓬松的毛发和狐狸般的面孔深受喜爱。', '长毛需每日梳理防打结。小型犬易有牙齿问题需注意口腔清洁。骨骼脆弱注意防摔伤。爱叫需从小训练。', 0, 13),
(29, 2, '吉娃娃', 'Chihuahua', '墨西哥', '忠诚警惕、勇敢活泼、对主人依赖', '12-20年', '1-3kg', '15-23cm', '短毛/长毛两种', '白色、黑色、棕色、奶油色、金色、三色', '吉娃娃是世界上最小的犬种，以墨西哥奇瓦瓦州命名。性格极其忠诚，对主人非常依赖。', '小型犬怕冷冬天需穿衣。骨骼脆弱注意防护。容易挑食需注意营养均衡。爱叫需耐心训练。', 0, 14),
(30, 2, '雪纳瑞犬', 'Schnauzer', '德国', '聪明活泼、勇敢忠诚、警惕性高', '12-15年', '5-9kg(迷你)', '30-36cm(迷你)', '刚毛，粗糙密实', '椒盐色(经典)、纯黑色、黑白', '雪纳瑞以标志性的胡子和眉毛著称，有迷你、标准、巨型三种体型。聪明勇敢，是非常好的看门犬。', '刚毛需定期拔毛或修剪。聪明易训练但有时会固执。精力充沛需要适量运动。', 0, 15),
(31, 2, '松狮犬', 'Chow Chow', '中国', '独立高傲、忠诚护主、安静沉稳', '9-15年', '20-32kg', '43-51cm', '长毛/短毛，厚密蓬松', '红色(经典)、黑色、蓝色、奶油色、肉桂色', '松狮犬是中国最古老的犬种之一，可追溯到汉朝。以其独特的蓝黑色舌头和狮子般的鬃毛著称。性格独立高傲。', '厚毛需经常梳理，夏季注意防暑。性格独立训练需耐心。易患髋关节和眼部疾病。', 0, 16),
(32, 2, '秋田犬', 'Akita', '日本', '忠诚勇敢、独立自信、对主人极其忠诚', '10-15年', '34-54kg', '58-70cm', '双层厚毛，外层刚硬', '红色(经典)、白色、虎斑色、芝麻色', '秋田犬是日本的国犬，以忠诚著称（忠犬八公的故事）。体型大、力量强，对家庭成员极其忠诚。', '需要大量运动和空间。性格强势需要经验丰富的主人。换毛季掉毛量极大。社交化训练必不可少。', 0, 17),
(33, 2, '中华田园犬', 'Chinese Rural Dog', '中国', '忠诚护主、聪明机警、身体素质极好', '12-17年', '15-30kg', '40-60cm', '短毛/中毛，致密', '黄色(最常见)、黑色、白色、四眼、棕色', '中华田园犬是中国本土家犬的统称，俗称土狗。身体素质极佳，聪明机警，看家护院能力出色。', '身体素质好不易生病。食物不挑剔容易喂养。忠诚度高是优秀的看门犬。建议定期驱虫和疫苗。', 0, 18);
INSERT IGNORE INTO `pet_breed` (`id`, `category_id`, `name`, `english_name`, `origin`, `personality`, `lifespan`, `weight`, `coat`, `colors`, `description`, `care_tips`, `is_featured`, `sort_order`) VALUES
(34, 3, '荷兰垂耳兔', 'Holland Lop', '荷兰', '温和友善、安静乖巧、喜安静', '7-12年', '1.5-2kg', '短毛/中毛，柔软浓密', '白色、黑色、棕色、灰色、三花、碎花色', '荷兰垂耳兔是最受欢迎的宠物兔品种之一，以其标志性的下垂耳朵和圆脸著称。体型小巧性格温顺。', '垂耳需定期检查清洁防感染。兔粮+干草+蔬菜均衡饮食。需磨牙物品。笼养需每日放风运动。', 1, 1),
(35, 3, '荷兰侏儒兔', 'Netherland Dwarf', '荷兰', '活泼好动、聪明好奇、性格较活泼', '7-12年', '0.5-1.2kg', '短毛，浓密有光泽', '白色、黑色、蓝色、巧克力色、灰色、橘色', '侏儒兔是世界上最小的宠物兔品种，成年体重仅0.5-1.2kg。体型迷你可爱但性格比大兔更活泼好动。', '体型小但精力旺盛需充足运动。对温度敏感怕冷怕热。牙齿易过长需充分磨牙。饮食以干草为主。', 0, 2),
(36, 3, '安哥拉兔', 'Angora Rabbit', '土耳其(安卡拉)', '温顺安静、喜静不喜动、毛发需要精心打理', '7-10年', '2.5-5kg', '长毛，浓密丝滑', '白色(最常见)、黑色、蓝色、奶油色、灰色', '安哥拉兔以其超长的丝滑毛发闻名，像一团行走的棉花糖。毛量丰富需要精心打理，是兔中贵族。', '长毛需每日梳理防打结。夏季注意防暑可适当剪毛。毛球症风险高需喂化毛膏。不适合毛发打理经验不足的主人。', 0, 3),
(37, 3, '狮子兔', 'Lionhead Rabbit', '比利时', '温和友善、活泼好奇、亲人可爱', '8-12年', '1.5-2.5kg', '短毛+颈部中长毛(鬃毛)', '白色、黑色、红色、灰色、三花、巧克力色', '狮子兔以其颈部周围的浓密鬃毛得名，酷似雄狮的鬃毛。性格温和亲人，是非常受欢迎的家庭宠物兔。', '颈部的鬃毛需经常梳理防打结。定期修剪指甲。提供充足干草和磨牙用品。性格温和适合儿童家庭。', 0, 4),
(38, 3, '雷克斯兔', 'Rex Rabbit', '法国', '温顺安静、性格稳定、毛质独特', '6-10年', '3-5kg', '短毛，绒面质地(无针毛)', '各种颜色均有可能', '雷克斯兔以其独特的绒面触感毛皮闻名，毛质像天鹅绒一样柔软（缺乏外层针毛）。性格极其温顺。', '独特毛质打理简单。体型较大需要更大的生活空间。性格温顺适合家庭饲养。注意营养均衡。', 0, 5),
(39, 3, '海棠兔', 'Hotot Rabbit', '法国/德国', '温和友善、性格安静、容易饲养', '8-12年', '1.5-3kg', '短毛，浓密', '纯白色+黑色眼线(特征)', '海棠兔又名熊猫兔或道奇兔，以纯白身体和独特的黑色眼圈闻名，酷似熊猫。性格温顺亲人。', '白色毛发需注意清洁。兔粮+无限量干草+蔬菜。性格温顺适合新手饲养。提供充足运动空间。', 0, 6),
(40, 3, '迷你雷克斯兔', 'Mini Rex', '美国', '温和友善、好奇心强、性格活泼', '7-10年', '1.5-2.5kg', '短毛，绒面质地', '多种颜色均可', '迷你雷克斯兔是雷克斯兔的迷你版本，在保留天鹅绒般毛质的同时体型更小。性格温和好奇。', '类似雷克斯兔但运动量稍大。迷你体型适合室内饲养。注意防摔防踩。需每日互动陪伴。', 0, 7);
INSERT IGNORE INTO `pet_breed` (`id`, `category_id`, `name`, `english_name`, `origin`, `personality`, `lifespan`, `weight`, `colors`, `description`, `care_tips`, `is_featured`, `sort_order`) VALUES
(41, 4, '虎皮鹦鹉', 'Budgerigar', '澳大利亚', '活泼好动、聪明好奇、喜群居爱说话', '5-10年', '30-40g', '绿色(原色)、蓝色、黄色、白色、紫色、灰色', '虎皮鹦鹉是全球最受欢迎的宠物鸟之一，体型小巧色彩丰富。雄鸟经过训练可以学说简单词汇和短语。', '笼子需足够大可飞翔。每日提供新鲜蔬菜水果。虎皮鹦鹉爱玩需准备玩具。定期修剪飞羽防逃逸。', 1, 1),
(42, 4, '玄凤鹦鹉', 'Cockatiel', '澳大利亚', '温顺友善、性格温和、爱吹口哨', '15-25年', '80-120g', '灰色(原色)、白色、黄色、珍珠色、肉桂色', '玄凤鹦鹉以其标志性的黄色冠羽和橙红色脸颊著称。性格温顺亲人，雄性擅长模仿口哨和简单旋律。', '寿命长需做好长期饲养准备。需要较大的笼子和每日出笼活动时间。喜社交需每天互动陪伴。', 0, 2),
(43, 4, '牡丹鹦鹉', 'Lovebird', '非洲', '活泼好动、感情丰富、需要伴侣', '10-15年', '40-60g', '绿色(原色)、蓝色、黄色、白色、桃面', '牡丹鹦鹉又名爱情鸟，因其与伴侣形影不离的特性得名。品种多样色彩艳丽，性格活泼好动。', '建议成对饲养不然主人需花大量时间陪伴。咬合力强需提供磨牙玩具。体型小但笼子需足够大。', 0, 3),
(44, 4, '金丝雀', 'Canary', '西班牙(加那利群岛)', '温顺安静、以鸣叫闻名、不喜打扰', '8-12年', '15-25g', '黄色(经典)、白色、红色、橙色、绿色', '金丝雀以优美的鸣叫声著称，尤其是德国罗勒金丝雀。雄鸟的鸣声婉转动听，是赏鸣首选。', '对环境污染敏感注意空气清新。需定期洗澡（喷雾或浅水盆）。提供钙质补充（墨鱼骨）。笼子需放置在安静处。', 0, 4),
(45, 4, '百灵鸟', 'Skylark', '欧洲/亚洲/非洲', '鸣声嘹亮、活泼好动、喜空旷环境', '5-8年', '30-50g', '褐色条纹(保护色)', '百灵鸟以其高亢嘹亮、婉转多变的鸣声闻名，被誉为草原上的歌唱家。在中国传统文化中深受喜爱。', '饲养难度较高需专业经验。需要大空间飞翔。饮食需昆虫和谷物混合。观赏为主不宜频繁打扰。', 0, 5),
(46, 4, '画眉鸟', 'Chinese Hwamei', '中国', '鸣声响亮动听、领地意识强、活泼好动', '8-12年', '50-75g', '橄榄褐色、白色眉纹(特征)', '画眉鸟因眼睛周围的白色眉纹而得名，是中国最著名的笼养鸟之一。鸣声多变响亮，深受中国鸟友喜爱。', '饲养需经验丰富的鸟友。鸣声洪亮早晨易扰民需考虑。需每日洗浴。杂食性需昆虫和植物性饲料搭配。', 0, 6),
(47, 4, '非洲灰鹦鹉', 'African Grey Parrot', '非洲中部/西部', '极其聪明、说话能力超强、情感丰富', '40-60年', '400-600g', '灰色身体+红色尾羽(刚果种)', '非洲灰鹦鹉被认为是鸟类中智商最高的物种，词汇量可达数百个。能理解人类的简单对话，是真正的"鸟类天才"。', '寿命极长需终身承诺。需要大量玩具和智力刺激。容易产生心理问题需充分陪伴。高昂的饲养成本和精力投入。', 0, 7),
(48, 4, '文鸟', 'Java Sparrow', '印度尼西亚(爪哇)', '温顺安静、喜群居、容易饲养', '5-8年', '20-30g', '灰色+白色脸颊+红色喙(原色)', '文鸟（爪哇禾雀）体型小巧、性格温顺，是非常适合初学者的宠物鸟。嘴部呈鲜艳的红色，十分可爱。', '适合新手入门饲养。喜群居建议成对或小群饲养。饮食以谷类为主。温顺不咬人适合儿童家庭。', 0, 8);
INSERT IGNORE INTO `pet_breed` (`id`, `category_id`, `name`, `english_name`, `origin`, `personality`, `lifespan`, `weight`, `colors`, `description`, `care_tips`, `is_featured`, `sort_order`) VALUES
(49, 5, '金鱼', 'Goldfish', '中国', '温顺安静、适应力强、喜群游', '5-10年(缸养可达20年)', '根据品种差异大', '红色、橙色、白色、黑色、五花、蓝色', '金鱼是中国最古老和最常见的观赏鱼，已有千年驯养历史。品种繁多，从普通的草金到华丽的兰寿，深受全球爱好者喜爱。', '鱼缸需足够大（每条约20升水）。过滤系统必不可少。不可过量喂食。定期换水保持水质。', 1, 1),
(50, 5, '锦鲤', 'Koi', '中国/日本', '温顺亲人、聪明可训练、体型大', '20-40年(甚至更长)', '可达10-90cm', '红白(经典)、大正三色、昭和三色、黄金、丹顶', '锦鲤被称为"水中活宝石"，是日本的国鱼。色彩斑斓、体型优雅，寿命可长达数十年。经过训练可从主人手中取食。', '需要池塘或大型鱼池饲养（至少2000升）。水质管理要求高。冬季需特殊过冬管理。高品质锦鲤价格昂贵。', 1, 2),
(51, 5, '孔雀鱼', 'Guppy', '南美洲(委内瑞拉)', '活泼好动、温和友善、繁殖力强', '1.5-3年', '2-6cm', '红色、蓝色、黄色、绿色、紫色、白色、黑色(雄鱼色彩丰富)', '孔雀鱼是全球最受欢迎的热带鱼之一，雄鱼尾鳍色彩斑斓如孔雀开屏。繁殖简单容易爆缸，是新手入门首选。', '适合新手入门。适宜水温22-28℃。繁殖能力强需控制数量。母鱼和幼鱼需隔离保护。', 0, 3),
(52, 5, '神仙鱼', 'Angelfish', '南美洲(亚马逊河流域)', '温和优雅、领地意识较强、喜安静', '8-12年', '可达15cm(体长)', '银色(原色)、黑色、金头、蓝翡翠、红眼白子', '神仙鱼以其优雅的三角形体型和长长的鳍条著称，是热带鱼爱好者的经典之选。在原生地可达15cm。', '需要较高（40cm+）的鱼缸以适应其体高。性情温和但成鱼有领地意识。水质要求较高需稳定管理。', 0, 4),
(53, 5, '斗鱼(泰国斗鱼)', 'Betta (Siamese Fighting Fish)', '泰国', '美丽好斗、领地意识极强、性格鲜明', '2-5年', '5-7cm', '红色、蓝色、紫色、白色、黄色、橙色、绿色(色彩极其丰富)', '泰国斗鱼以其极致的色彩和飘逸的鳍条成为观赏鱼界的明星。雄鱼之间会激烈打斗，故必须单养。', '雄鱼必须单独饲养不能混养。适宜水温24-30℃。可直接呼吸空气不需打氧。喜欢弱水流和躲藏处。', 0, 5),
(54, 5, '红绿灯鱼', 'Neon Tetra', '南美洲(亚马逊河流域)', '温顺活泼、喜群游、胆小', '3-5年', '3-4cm', '红色+蓝绿色条纹(经典)、银色腹部', '红绿灯鱼是最经典的热带观赏鱼之一，体侧有一条绚丽的蓝绿色和红色条纹。群游时效果极佳，是草缸必备品种。', '喜群游建议6条以上一起养。适宜水温22-28℃。胆小需提供水草躲避处。对水质波动敏感。', 0, 6),
(55, 5, '龙鱼', 'Asian Arowana', '东南亚(亚洲)', '威武霸气、领地意识强、性格凶猛', '10-30年', '可达60-90cm', '金色(金龙)、红色(红龙)、银色(银龙)、青龙', '龙鱼是观赏鱼界的顶级品种，被誉为"水中活龙"。亚洲龙鱼为国家保护动物，在中华文化中象征吉祥和财富。', '需要超大型鱼缸（至少300升以上）。顶级龙鱼价格可达数百万。水质要求极高。需专业设备和管理。', 0, 7),
(56, 5, '七彩神仙鱼', 'Discus', '南美洲(亚马逊河流域)', '威严优雅、喜群游、需要稳定环境', '6-12年', '可达15-20cm', '红色、蓝色、绿色、棕色、白色(图案极为丰富)', '七彩神仙鱼被誉为"热带鱼之王"，体型圆盘状、色彩变幻莫测。是观赏鱼饲养中最高难度的挑战之一。', '饲养难度极高适合有经验的鱼友。水温需稳定在28-30℃。水质要求极高需要频繁换水。对噪音和振动敏感。', 0, 8);
INSERT IGNORE INTO `pet_breed` (`id`, `category_id`, `name`, `english_name`, `origin`, `personality`, `lifespan`, `weight`, `colors`, `description`, `care_tips`, `is_featured`, `sort_order`) VALUES
(57, 6, '红耳龟(巴西龟)', 'Red-eared Slider', '美国(密西西比河流域)', '活泼好动、适应力强、攻击性较强', '20-30年', '20-40cm(甲长)', '绿色+红色耳斑(特征)、黄色条纹', '红耳龟俗称巴西龟，是全球最常见的宠物龟。以头部两侧的红色斑纹为特征，幼体翠绿可爱但成体体型较大。', '需大型水陆缸（成龟需200升以上）。需晒台和UVB灯。杂食性注意钙质补充。已被列为入侵物种切勿放生。', 1, 1),
(58, 6, '中华草龟', 'Chinese Pond Turtle', '中国', '温顺安静、性格温和、耐受力强', '20-30年', '10-25cm(甲长)', '褐色/黑色(雄龟成体变墨)、黄色条纹', '中华草龟是中国本土最常见的龟类，也是中国传统文化中"长寿"的象征。雄龟成年后会逐渐变黑成为"墨龟"。', '水陆两栖需设置晒台。需要冬眠（5-10℃）。杂食性偏素食。体型适中适合家庭饲养。', 0, 2),
(59, 6, '陆龟(辐射陆龟)', 'Radiated Tortoise', '马达加斯加', '温顺安静、行动缓慢、寿命极长', '40-100年', '可达30-40cm(甲长)', '黑色背甲+黄色放射状条纹(特征)', '辐射陆龟以其背甲上精美的辐射状条纹被称为世界上最美丽的陆龟之一。寿命极长可达百年，是龟中贵族。', '需要大空间和户外活动区。需要UVB灯和恒温设备。严格的素食饮食。幼体需注意湿度控制。价格较高且需合法来源。', 0, 3),
(60, 6, '鬃狮蜥', 'Bearded Dragon', '澳大利亚', '温顺亲人、性格稳重、好奇友善', '8-12年', '35-60cm', '黄色、橙色、红色、灰色、白色(多种色系)', '鬃狮蜥是世界上最受欢迎的宠物蜥蜴之一，因其受惊时喉部会膨胀变黑像胡须而得名。性格温顺极易上手。', '需UVB灯和加热灯。杂食性需昆虫+蔬菜搭配。每日需喷雾补水。温顺可上手互动。适合爬宠入门者。', 0, 4),
